#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Trois ajouts demandes :

1) Separer commandes livrees / non livrees : le filtre "Etat des
   travaux" de la liste des commandes (auparavant vide/inoperant,
   base sur un champ jamais mis a jour) propose maintenant de vrais
   choix -- En preparation / En livraison / Livree -- calcules a
   partir du statut reel des lignes.

2) Actualisation automatique de la Vue d'ensemble production
   (/production/apercu), toutes les 90 secondes, pour l'ecran
   affiche en continu en atelier.

3) Alerte sonore au controle prepresse : des qu'une nouvelle ligne
   arrive dans la file "a controler" (fichiers en attente de
   verification), un bip se repete toutes les 1,5 seconde jusqu'a ce
   qu'un agent clique sur "Couper le son". Verification automatique
   toutes les 20 secondes. Le son est genere directement par le
   navigateur (aucun fichier audio necessaire).

Executer depuis la racine du projet :
    python3 livraison_filtre_refresh_alerte_prepresse.py
"""

import sys


def appliquer(chemin, ancien, nouveau, label):
    try:
        with open(chemin, "r", encoding="utf-8") as f:
            contenu = f.read()
    except FileNotFoundError:
        print(f"[ERREUR] Fichier introuvable : {chemin}")
        return False

    if nouveau in contenu:
        print(f"[SKIP] {label} : deja applique.")
        return True

    occurrences = contenu.count(ancien)

    if occurrences != 1:
        print(
            f"[ERREUR] {label} : {occurrences} occurrence(s) trouvee(s) "
            f"dans {chemin} (1 attendue)"
        )
        return False

    contenu = contenu.replace(ancien, nouveau)

    with open(chemin, "w", encoding="utf-8") as f:
        f.write(contenu)

    print(f"[OK] {label}")
    return True


